-- Phase 8 additive migration. Keeps hosts/listings intact.
begin;
create extension if not exists pgcrypto;
create table if not exists destinations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,province text,country_code text not null default 'TH',timezone text not null default 'Asia/Bangkok',status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now());
create table if not exists businesses(id uuid primary key default gen_random_uuid(),legacy_host_id uuid unique references hosts(id) on delete set null,owner_user_id uuid,name text not null,phone text,line_id text,email text,status text not null default 'pending' check(status in('pending','active','inactive','suspended')),verification_status text not null default 'unverified' check(verification_status in('unverified','pending','verified','rejected','stale')),last_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists business_members(business_id uuid references businesses(id) on delete cascade,user_id uuid not null,role text not null default 'owner' check(role in('owner','admin','editor','viewer')),primary key(business_id,user_id));
create table if not exists places(id uuid primary key default gen_random_uuid(),legacy_listing_id uuid unique references listings(id) on delete set null,business_id uuid references businesses(id) on delete set null,destination_id uuid references destinations(id),place_type text not null check(place_type in('accommodation','restaurant','cafe','attraction','activity')),name text not null,slug text unique not null,description text,address text,latitude double precision check(latitude is null or latitude between -90 and 90),longitude double precision check(longitude is null or longitude between -180 and 180),google_maps_url text,min_group_size integer check(min_group_size is null or min_group_size>0),max_group_size integer check(max_group_size is null or max_group_size>0),recommended_duration_minutes integer check(recommended_duration_minutes is null or recommended_duration_minutes>0),pet_friendly boolean,child_friendly boolean,elderly_friendly boolean,accessibility_supported boolean,parking_available boolean,reservation_required boolean not null default false,weather_sensitive boolean not null default false,publication_status text not null default 'draft' check(publication_status in('draft','pending','published','rejected','archived')),verification_status text not null default 'unverified' check(verification_status in('unverified','pending','verified','rejected','stale')),last_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(max_group_size is null or min_group_size is null or max_group_size>=min_group_size));
create table if not exists accommodation_details(place_id uuid primary key references places(id) on delete cascade,accommodation_type text,check_in_time time,check_out_time time,maximum_guests integer check(maximum_guests is null or maximum_guests>0));
create table if not exists dining_details(place_id uuid primary key references places(id) on delete cascade,cuisine_types text[] not null default '{}',meal_periods text[] not null default '{}',average_spend_per_person numeric check(average_spend_per_person is null or average_spend_per_person>=0));
create table if not exists attraction_details(place_id uuid primary key references places(id) on delete cascade,attraction_type text,ticket_required boolean not null default false);
create table if not exists activity_details(place_id uuid primary key references places(id) on delete cascade,activity_type text,minimum_age integer check(minimum_age is null or minimum_age>=0),equipment_included boolean);
create table if not exists place_images(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,image_url text not null,alt_text text,sort_order integer not null default 0,is_cover boolean not null default false,unique(place_id,image_url));
create table if not exists place_hours(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,day_of_week smallint not null check(day_of_week between 0 and 6),open_time time,close_time time,is_closed boolean not null default false,crosses_midnight boolean not null default false,check(is_closed or(open_time is not null and close_time is not null)));
create table if not exists place_special_hours(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,service_date date not null,open_time time,close_time time,is_closed boolean not null default false,note text,check(is_closed or(open_time is not null and close_time is not null)));
create table if not exists events(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete set null,place_id uuid references places(id) on delete set null,destination_id uuid references destinations(id),name text not null,slug text unique not null,description text,temporary_venue_name text,address text,latitude double precision,longitude double precision,publication_status text not null default 'draft' check(publication_status in('draft','pending','published','rejected','archived')),verification_status text not null default 'unverified',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists event_schedules(id uuid primary key default gen_random_uuid(),event_id uuid not null references events(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'scheduled' check(status in('scheduled','cancelled','sold_out','completed')),check(ends_at>starts_at));
create table if not exists price_items(id uuid primary key default gen_random_uuid(),place_id uuid references places(id) on delete cascade,event_id uuid references events(id) on delete cascade,label text not null,amount_min numeric not null default 0 check(amount_min>=0),amount_max numeric, currency text not null default 'THB',price_unit text not null check(price_unit in('free','person','group','night','room','activity','item')),is_estimate boolean not null default false,check((place_id is not null)<>(event_id is not null)));
create table if not exists tags(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,tag_group text not null default 'general',is_editorial boolean not null default false);
create table if not exists place_tags(place_id uuid references places(id) on delete cascade,tag_id uuid references tags(id) on delete cascade,source text not null default 'curated',primary key(place_id,tag_id));
create table if not exists place_relationships(id uuid primary key default gen_random_uuid(),from_place_id uuid references places(id) on delete cascade,to_place_id uuid references places(id) on delete cascade,relationship_type text not null,reason text,estimated_travel_minutes integer,distance_km numeric,source_url text,last_verified_at timestamptz,check(from_place_id<>to_place_id));
create table if not exists place_sources(id uuid primary key default gen_random_uuid(),place_id uuid references places(id) on delete cascade,source_type text not null,source_url text,source_note text,checked_at timestamptz not null default now(),checked_by uuid);
create index if not exists places_lookup_idx on places(destination_id,place_type,publication_status);create index if not exists hours_lookup_idx on place_hours(place_id,day_of_week);create index if not exists event_window_idx on event_schedules(starts_at,ends_at,status);
insert into destinations(name,slug,province) values('ปากช่อง–เขาใหญ่','pak-chong-khao-yai','นครราชสีมา') on conflict(slug) do nothing;
insert into businesses(legacy_host_id,owner_user_id,name,phone,line_id,email,status,created_at,updated_at) select id,user_id,coalesce(nullif(business_name,''),nullif(contact_name,''),'Legacy business'),phone,line_id,email,case when status in('active','inactive','pending') then status else 'pending' end,created_at,updated_at from hosts on conflict(legacy_host_id) do nothing;
insert into business_members(business_id,user_id) select id,owner_user_id from businesses where owner_user_id is not null on conflict do nothing;
insert into places(legacy_listing_id,business_id,destination_id,place_type,name,slug,description,address,latitude,longitude,google_maps_url,max_group_size,pet_friendly,publication_status,created_at,updated_at) select l.id,b.id,d.id,'accommodation',coalesce(l.name,'Unnamed accommodation'),coalesce(nullif(l.slug,''),'legacy-'||l.id),l.description,coalesce(l.address,l.location),l.latitude,l.longitude,l.google_maps_url,l.capacity,l.pet_friendly,case when l.status in('draft','pending','published','rejected','archived') then l.status else 'draft' end,l.created_at,l.updated_at from listings l left join businesses b on b.legacy_host_id=l.host_id cross join destinations d where d.slug='pak-chong-khao-yai' on conflict(legacy_listing_id) do nothing;
insert into accommodation_details(place_id,accommodation_type,maximum_guests) select p.id,l.category,l.capacity from places p join listings l on l.id=p.legacy_listing_id on conflict(place_id) do nothing;
insert into price_items(place_id,label,amount_min,price_unit,is_estimate) select p.id,'Legacy listing price',coalesce(l.price,0),case when lower(coalesce(l.price_unit,'')) like '%คน%' then 'person' when lower(coalesce(l.price_unit,'')) like '%กลุ่ม%' then 'group' when lower(coalesce(l.price_unit,'')) like '%ห้อง%' then 'room' else 'night' end,true from places p join listings l on l.id=p.legacy_listing_id where l.price is not null and not exists(select 1 from price_items x where x.place_id=p.id and x.label='Legacy listing price');
insert into place_images(place_id,image_url,sort_order,is_cover) select p.id,x.url,x.n-1,x.n=1 from places p join listings l on l.id=p.legacy_listing_id cross join lateral unnest(coalesce(l.images,'{}'::text[])) with ordinality x(url,n) where true on conflict(place_id,image_url) do nothing;
insert into place_images(place_id,image_url,sort_order) select p.id,i.image_url,i.sort_order from places p join listing_images i on i.listing_id=p.legacy_listing_id on conflict(place_id,image_url) do nothing;
create or replace view legacy_listing_place_map as select l.id listing_id,l.slug listing_slug,p.id place_id,p.slug place_slug from listings l join places p on p.legacy_listing_id=l.id;
alter table businesses enable row level security;alter table business_members enable row level security;alter table places enable row level security;alter table place_images enable row level security;alter table place_hours enable row level security;alter table place_special_hours enable row level security;alter table events enable row level security;alter table event_schedules enable row level security;alter table price_items enable row level security;
drop policy if exists "Public published places" on places;create policy "Public published places" on places for select using(publication_status='published');
drop policy if exists "Members manage places" on places;create policy "Members manage places" on places for all to authenticated using(exists(select 1 from business_members m where m.business_id=places.business_id and m.user_id=auth.uid() and m.role in('owner','admin','editor'))) with check(exists(select 1 from business_members m where m.business_id=places.business_id and m.user_id=auth.uid() and m.role in('owner','admin','editor')));
drop policy if exists "Members read memberships" on business_members;create policy "Members read memberships" on business_members for select to authenticated using(user_id=auth.uid());
drop policy if exists "Public published events" on events;create policy "Public published events" on events for select using(publication_status='published');
commit;
